type Kind = "literal" | "parameter" | "wildcard";
const SCORE: Record<Kind, number> = { literal: 3, parameter: 2, wildcard: 1 };

function kinds(pattern: string): Kind[] {
  return pattern.split("/").filter(Boolean).map((s) => (s.startsWith(":") ? "parameter" : s.startsWith("*") ? "wildcard" : "literal"));
}

function compare(left: Kind[], right: Kind[]): number {
  for (let i = 0; i < Math.max(left.length, right.length); i++) {
    const difference = (right[i] ? SCORE[right[i]!] : 0) - (left[i] ? SCORE[left[i]!] : 0);
    if (difference !== 0) return difference;
  }
  return 0;
}

