function toResponse(error: unknown): string {
  const e = error as { statusCode?: unknown; expose?: unknown; message?: unknown };
  const status = typeof e?.statusCode === "number" && e.statusCode >= 400 && e.statusCode <= 599 ? e.statusCode : undefined;
  if (status === undefined) return "500 Internal Server Error";
  return `${status} ${e.expose === true ? e.message : "(status text)"}`;
}

