function excerpt(text: string, from: RegExp, count: number): string {
  const lines = text.split("\n");
  const start = lines.findIndex((line) => from.test(line));
  if (start === -1) throw new Error(`${from} not found`);
  return lines
    .slice(start, start + count)
    .map((line, i) => `${String(start + i + 1).padStart(3, "0")}  ${line}`)
    .join("\n");
}

