function reexports(text: string): string[] {
  return [...text.matchAll(/^export \* from "([^"]+)";/gm)].map((m) => m[1]!);
}

function explicit(text: string): string[] {
  return [...text.matchAll(/^export \{([^}]*)\} from/gm)].flatMap((m) => m[1]!.split(",").map((name) => name.trim()).filter(Boolean));
}

