type Lifetime = "singleton" | "scoped" | "transient";
const registry: Record<string, { lifetime: Lifetime; deps: string[] }> = {
  Report: { lifetime: "singleton", deps: ["Formatter"] },
  Formatter: { lifetime: "transient", deps: ["Cart"] },
  Cart: { lifetime: "scoped", deps: [] },
  Checkout: { lifetime: "transient", deps: ["Cart"] },
};

function resolve(token: string, singletonAncestor?: string): string {
  const registration = registry[token]!;
  if (registration.lifetime === "scoped" && singletonAncestor !== undefined) {
    throw new Error(`captive: ${singletonAncestor} -> ${token}`);
  }
  const next = registration.lifetime === "singleton" ? token : singletonAncestor;
  for (const dep of registration.deps) resolve(dep, next);
  return token;
}

for (const token of ["Checkout", "Formatter", "Report"]) {
  try {
    console.log(`${token}: ${resolve(token)}`);
  } catch (error) {
    console.log(`${token}: ${(error as Error).message}`);
  }
}

