let sorts = 0;
const byKind = (a: string, b: string) => Number(a.includes(":")) - Number(b.includes(":"));

class SortOnMatch {
  constructor(private readonly routes: string[]) {}
  match(): string {
    sorts++;
    return [...this.routes].sort(byKind)[0]!;
  }
}

class SortOnRegister {
  private readonly routes: string[];
  constructor(routes: string[]) {
    sorts++;
    this.routes = [...routes].sort(byKind);
  }
  match(): string {
    return this.routes[0]!;
  }
}

const routes = ["/books/:id", "/books/new"];
const a = new SortOnMatch(routes);
const first = [a.match(), a.match(), a.match()];
console.log(first[0], "sorts:", sorts);
sorts = 0;
const b = new SortOnRegister(routes);
const second = [b.match(), b.match(), b.match()];
console.log(second[0], "sorts:", sorts);

const deps: Record<string, string[]> = { Orders: ["Payments"], Payments: ["Invoices"], Invoices: ["Orders"], Clock: [] };

function resolve(token: string, path: string[] = [], seen = new Set<string>()): string {
  if (seen.has(token)) throw new Error(`circular: ${[...path, token].join(" -> ")}`);
  path.push(token);
  seen.add(token);
  try {
    for (const dep of deps[token] ?? []) resolve(dep, path, seen);
    return token;
  } finally {
    path.pop();
    seen.delete(token);
  }
}

for (const token of ["Clock", "Payments"]) {
  try {
    console.log(resolve(token));
  } catch (error) {
    console.log((error as Error).message);
  }
}

