class PipelineError extends Error {}
const withStatus = (message: string, statusCode: number, cause?: unknown) => Object.assign(new Error(message, { cause }), { statusCode });

function findStatus(error: unknown, depth = 0): number {
  if (typeof error !== "object" || error === null || depth > 8) return 500;
  const status = (error as { statusCode?: unknown }).statusCode;
  if (typeof status === "number" && status >= 400 && status <= 599) return status;
  if (error instanceof PipelineError) return findStatus(error.cause, depth + 1);
  return 500;
}

const notFound = withStatus("Book b9 not found", 404);
console.log(
  findStatus(notFound),
  findStatus(new PipelineError("middleware failed", { cause: notFound })),
  findStatus(new Error("app error", { cause: notFound })),
  findStatus(withStatus("Bad Gateway", 502, withStatus("upstream said no", 401))),
);
